def fast(a):
 n=len(a); a=[n+1]+a+[0]; dp=[1]+[0]*(n+1)
 for r in range(1,n+2):
  for l in range(r):
   if a[l]<=a[r]:continue
   v=[a[k] for k in range(l+1,r) if a[r]<a[k]<a[l]]
   if not any(all((x<z and y>w) or (x>z and y<w) for z,w in enumerate(v) if z!=x) for x,y in enumerate(v)):
    dp[r]+=dp[l]
 return dp[-1]
def brute(a):
 n=len(a); adj=[sum(1<<j for j in range(n) if (i-j)*(a[i]-a[j])>0) for i in range(n)]
 seen={(1<<n)-1}; stack=list(seen)
 while stack:
  s=stack.pop()
  for i in range(n):
   if s>>i&1:
    t=s&~adj[i]
    if t not in seen:seen.add(t);stack.append(t)
 return len(seen)
for n in range(1,9):
 for _ in range(300):
  a=list(range(1,n+1));random.shuffle(a)
  x,y=fast(a),brute(a)
  if x!=y:print('BAD',a,x,y);raise SystemExit
