MOD = 998244353

def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(data)
    m = next(data)

    # limits[l][k]: smallest right endpoint of a condition at k
    # whose left endpoint is at least l (endpoints are half-open).
    limits = [[n + 1] * n for _ in range(n)]
    for _ in range(m):
        l = next(data) - 1
        r = next(data)
        x = next(data) - 1
        if r == l + 1:
            print(0)
            return
        if r < limits[l][x]:
            limits[l][x] = r

    factorial = 1
    for i in range(2, n + 1):
        factorial = factorial * i % MOD
    if m == 0:
        print(factorial)
        return

    for l in range(n - 2, -1, -1):
        current = limits[l]
        following = limits[l + 1]
        for k in range(l + 1, n):
            if following[k] < current[k]:
                current[k] = following[k]

    inverse = [0] * (n + 1)
    inverse[1] = 1
    for i in range(2, n + 1):
        inverse[i] = MOD - (MOD // i) * inverse[MOD % i] % MOD

    # dp[l][r] is the valid count on [l,r), divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for l in range(n, -1, -1):
        row = dp[l]
        row[l] = 1
        if l == n:
            continue
        limit = limits[l]
        for r in range(l + 1, n + 1):
            total = 0
            for k in range(l, r):
                if r < limit[k]:
                    total += row[k] * dp[k + 1][r]
            row[r] = total % MOD * inverse[r - l] % MOD

    print(dp[0][n] * factorial % MOD)

if __name__ == '__main__':
    main()

