import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    degree = [0] * n
    for p in a:
        degree[p] += 1
    q = deque(i for i in range(n) if degree[i] == 0)
    dp = [None] * n
    while q:
        v = q.popleft()
        p = a[v]
        child = dp[v]
        parent = dp[p]
        if child is None:
            if parent is None:
                dp[p] = list(range(1, m + 1))
            else:
                for j in range(m):
                    parent[j] = parent[j] * (j + 1) % MOD
        else:
            total = 0
            if parent is None:
                for j in range(m):
                    total = (total + child[j]) % MOD
                    child[j] = total
                dp[p] = child
            else:
                for j in range(m):
                    total = (total + child[j]) % MOD
                    parent[j] = parent[j] * total % MOD
        dp[v] = None
        degree[p] -= 1
        if degree[p] == 0:
            q.append(p)
    answer = 1
    for start in range(n):
        if degree[start] == 0:
            continue
        v = start
        product = None
        while degree[v]:
            degree[v] = 0
            cur = dp[v]
            if cur is not None:
                if product is None:
                    product = cur
                else:
                    for j in range(m):
                        product[j] = product[j] * cur[j] % MOD
            dp[v] = None
            v = a[v]
        ways = m if product is None else sum(product) % MOD
        answer = answer * ways % MOD
    print(answer)

if __name__ == '__main__':
    main()

