import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    events = {}

    for i, x in enumerate(data[1:], 1):
        p = 2
        while p * p <= x:
            if x % p == 0:
                exponent = 0
                while x % p == 0:
                    x //= p
                    exponent += 1
                events.setdefault(p, []).append((i, exponent))
            p += 1
        if x > 1:
            events.setdefault(x, []).append((i, 1))

    answer = 1
    for p, prime_events in events.items():
        # Height is the current exponent minus the minimum so far.
        # Weights already include the current height for all future entries.
        dp = [1]
        for i, a in prime_events:
            up = pow(p, a * (n - i), MOD)
            down = pow(up, MOD - 2, MOD)
            new_dp = [0] * (len(dp) + a)

            for h, value in enumerate(dp):
                new_dp[h + a] = value * up % MOD

            for h in range(a, len(dp)):
                new_dp[h - a] = (new_dp[h - a] + dp[h] * down) % MOD

            # A new minimum requires shifting all n exponents upward.
            for h in range(min(a, len(dp))):
                factor = pow(p, a * i - n * h, MOD)
                new_dp[0] = (new_dp[0] + dp[h] * factor) % MOD

            dp = new_dp

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)


if __name__ == '__main__':
    main()

