def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    m = max(a)
    omega = bytearray(m + 1)
    for p in range(2, m + 1):
        if omega[p] == 0:
            power = p
            while power <= m:
                for j in range(power, m + 1, power):
                    omega[j] += 1
                power *= p
    result = 0
    for v in a:
        result ^= omega[v]
    print('Anna' if result else 'Bruno')

if __name__ == '__main__':
