from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, i))

        gain = [0] * len(conflictingPairs)
        first = second = 0
        first_id = -1
        total = 0
        for right in range(1, n + 1):
            for left, pair_id in ending[right]:
                if left > first:
                    second = first
                    first = left
                    first_id = pair_id
                elif left > second:
                    second = left
            total += right - first
            if first_id != -1:
                gain[first_id] += first - second
        return total + max(gain)

