import sys


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n, m, q = next(it), next(it), next(it)
    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    queries = []
    closed = bytearray(m)
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            closed[e] = 1
            queries.append((1, e))
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**18
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, w) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = w

    rng = range(n)
    for k in rng:
        dk = d[k]
        for i in rng:
            di = d[i]
            v = di[k]
            if v == inf:
                continue
            for j in rng:
                nd = v + dk[j]
                if nd < di[j]:
                    di[j] = nd

    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            value = d[query[1]][query[2]]
            ans.append(str(value if value < inf else -1))
        else:
            a, b, w = edges[query[1]]
            if d[a][b] <= w:
                continue
            da, db = d[a][:], d[b][:]
            for i in rng:
                di = d[i]
                va, vb = da[i] + w, db[i] + w
                if va >= inf and vb >= inf:
                    continue
                for j in range(i + 1, n):
                    nd = va + db[j]
                    other = vb + da[j]
                    if other < nd:
                        nd = other
                    if nd < di[j]:
                        di[j] = d[j][i] = nd

    sys.stdout.write('\n'.join(reversed(ans)))


if __name__ == '__main__':
    main()

