import sys
from functools import lru_cache


def main():
    A, B, M = map(int, sys.stdin.buffer.read().split())
    n = A * B - 1
    fact = 1
    for k in range(2, n + 1):
        fact = fact * k % M
    hooks = 1
    for r in range(B):
        width = A - (r == B - 1)
        for c in range(width):
            below = B - r - 1 - (c == A - 1)
            hooks = hooks * (width - c + below) % M
    recording_count = fact * pow(hooks, M - 2, M) % M

    if A < B:
        target = (B,) * (A - 1) + (B - 1,)
        h = A

        @lru_cache(None)
        def dp(s):
            if s == target:
                return 1
            total = 0
            for i, v in enumerate(s):
                if v == target[i] or (i and v >= s[i - 1]):
                    continue
                if i == h - 1 and s[i - 1] < v + 2:
                    continue
                total += dp(s[:i] + (v + 1,) + s[i + 1:])
            return total % M
    else:
        target = (A,) * (B - 1) + (A - 1,)
        h = B

        @lru_cache(None)
        def dp(s):
            if s == target:
                return 1
            total = 0
            for i, v in enumerate(s):
                if v == target[i] or (i and v >= s[i - 1]):
                    continue
                if v == A - 1 and s[i + 1] < A - 1:
                    continue
                total += dp(s[:i] + (v + 1,) + s[i + 1:])
            return total % M

    print(recording_count * dp((0,) * h) % M)


