import sys
from math import gcd

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    rows = []
    upper = 10**9
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        upper = min(upper, max(budget * a // p, budget * b // q))
        if p * b > q * a:
            a, p, b, q = b, q, a, p
        rows.append((a, p, b, q, a // gcd(a, b)))

    def feasible(w):
        total = 0
        for a, p, b, q, limit in rows:
            best = ((w + a - 1) // a) * p
            for k in range(1, min(limit - 1, (w + b - 1) // b) + 1):
                remaining = w - k * b
                cost = k * q
                if remaining > 0:
                    cost += ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, upper + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == '__main__':
    main()

