class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)
        steps = [0] * (length + 1)
        for x in range(2, length + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # dp[j] counts prefixes already strictly smaller, with j set bits.
        dp = [0] * (length + 1)
        ones = 0
        for i, bit in enumerate(s):
            for j in range(i + 1, 0, -1):
                dp[j] = (dp[j] + dp[j - 1]) % mod
            if bit == '1':
                # Choose zero here after matching all preceding bits.
                dp[ones] = (dp[ones] + 1) % mod
                ones += 1

        return sum(dp[x] for x in range(1, length + 1)
                   if steps[x] < k) % mod

