import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    rows = [0] * n
    for i in range(m):
        u, v = data[2 + 2 * i] - 1, data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for c in range(n):
        bit = 1 << c
        p = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= rows[rank]
        pivots.append(c)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    values = [0] * n
    offset = min(2, 60 - len(free)) if m else 0

    # Pack one nullspace basis vector into each used bit position.
    for k, c in enumerate(free):
        values[c] = 1 << (k + offset)
    for i, c in enumerate(pivots):
        for f in free:
            if rows[i] & (1 << f):
                values[c] ^= values[f]

    # A zero coordinate in every basis vector can never be nonzero.
    if any(x == 0 for x in values):
        print('No')
    else:
        print('Yes')
        print(*values)


if __name__ == '__main__':
    main()

