from math import isqrt

def main():
    n = int(sys.stdin.buffer.readline())
    # Let d = x-y. Then n/d = 3*y*y + 3*d*y + d*d.
    for d in range(1, 1000001):
        if d*d*d >= n:
            break
        if n % d:
            continue
        q = n // d
        disc = 12*q - 3*d*d
        s = isqrt(disc)
        if s*s == disc and s > 3*d and (s-3*d) % 6 == 0:
            y = (s-3*d)//6
            print(y+d, y)
            return
    print(-1)

