class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        a = [v for row in grid for v in row]
        ans = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            er, ec = dc, -dr
            tail = [1] * (n * m)
            rows = range(n - 1, -1, -1) if er == 1 else range(n)
            for r in rows:
                nr = r + er
                if not 0 <= nr < n:
                    continue
                base, nb = r * m, nr * m
                for c in range(m):
                    nc = c + ec
                    if 0 <= nc < m:
                        i, j = base + c, nb + nc
                        want = 2 if a[i] == 1 else 2 - a[i]
                        if a[j] == want:
                            tail[i] = 1 + tail[j]
            prev = [0] * m
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            for r in rows:
                cur = [0] * m
                base = r * m
                pb = (r - dr) * m
                for c in range(m):
                    i = base + c
                    if a[i] == 1:
                        cur[c] = 1
                    else:
                        pc = c - dc
                        if 0 <= pc < m and prev[pc]:
                            pv = a[pb + pc]
                            if a[i] == (2 if pv == 1 else 2 - pv):
                                cur[c] = prev[pc] + 1
                    if cur[c]:
                        ans = max(ans, cur[c] + tail[i] - 1)
                prev = cur
        return ans

