from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odds = (n + 1) // 2
        evens = n // 2
        remaining = list(range(1, n + 1))
        answer = []
        required = 1 if n % 2 else None

        while remaining:
            for i, value in enumerate(remaining):
                parity = value % 2
                if required is not None and parity != required:
                    continue
                o = odds - parity
                e = evens - (1 - parity)
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    remaining.pop(i)
                    odds, evens = o, e
                    required = 1 - parity
                    break
            else:
                return []
        return answer

