from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        half = (n + 1) // 2
        weights = [0] * half
        for i in range(half):
            j = n - 1 - i
            if i == j:
                weights[i] = powers[i] % k
            else:
                weights[i] = (powers[i] + powers[j]) % k

        # Digits 0..9 cover every residue modulo k. Consequently,
        # suffix sums attain exactly the multiples of this suffix gcd.
        suffix = [k] * (half + 1)
        for i in range(half - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])

        result = ['0'] * n
        remainder = 0
        for i in range(half):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                candidate = (remainder + digit * weights[i]) % k
                if candidate % suffix[i + 1] == 0:
                    result[i] = result[n - 1 - i] = str(digit)
                    remainder = candidate
                    break

        return ''.join(result)

