import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    counts = {}
    for i in range(2, len(data), 2):
        pair = (data[i], data[i + 1])
        counts[pair] = min(k, counts.get(pair, 0) + 1)

    # Apply functions in ascending order of (A - 1) / B.
    # With A, B <= 50, floats distinguish all unequal such ratios.
    pairs = sorted(counts, key=lambda p: (p[0] - 1) / p[1])
    dp = [-1] * (k + 1)
    dp[0] = 1
    seen = 0
    for a, b in pairs:
        for _ in range(counts[(a, b)]):
            seen += 1
            for j in range(min(k, seen), 0, -1):
                if dp[j - 1] != -1:
                    value = a * dp[j - 1] + b
                    if value > dp[j]:
                        dp[j] = value
    print(dp[k])

if __name__ == '__main__':
    main()

