class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        grouped = [[] for _ in range(n)]
        for k, (l, r) in enumerate(queries):
            grouped[l].append((r, k))
        answer = [0] * len(queries)
        score = [0] * n
        best = [0] * n
        for i in range(n - 1, -1, -1):
            current = maximum = nums[i]
            score[i] = best[i] = current
            for j in range(i + 1, n):
                current ^= score[j]
                score[j] = current
                if best[j] > maximum:
                    maximum = best[j]
                if current > maximum:
                    maximum = current
                best[j] = maximum
            for r, k in grouped[i]:
                answer[k] = best[r]
        return answer

