import sys
import heapq


def solve():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    N = next(it)
    W = next(it)
    groups = {}
    for _ in range(N):
        w = next(it)
        v = next(it)
        if v > 1:
            groups.setdefault(w, []).append(1 - v)

    dp = [0] * (W + 1)
    for w, heap in groups.items():
        heapq.heapify(heap)
        # Marginal happiness values are v-1, v-3, v-5, ... .
        gain = [0]
        for _ in range(W // w):
            if heap[0] >= 0:
                break
            t = heap[0]
            gain.append(gain[-1] - t)
            heapq.heapreplace(heap, t + 2)
        count = len(gain) - 1

        if count <= 8:
            for k in range(1, count + 1):
                value = gain[k] - gain[k - 1]
                for capacity in range(W, w - 1, -1):
                    candidate = dp[capacity - w] + value
                    if candidate > dp[capacity]:
                        dp[capacity] = candidate
        else:
            # Concavity of gain makes the maximizing previous index
            # monotone, allowing divide-and-conquer optimization.
            for residue in range(w):
                old = dp[residue::w]
                length = len(old)
                new = [0] * length

                def compute(left, right, opt_left, opt_right):
                    if left > right:
                        return
                    mid = (left + right) // 2
                    best = -1
                    best_index = -1
                    start = max(opt_left, mid - count)
                    end = min(opt_right, mid)
                    for j in range(start, end + 1):
                        candidate = old[j] + gain[mid - j]
                        if candidate > best:
                            best = candidate
                            best_index = j
                    new[mid] = best
                    compute(left, mid - 1, opt_left, best_index)
                    compute(mid + 1, right, best_index, opt_right)

                compute(0, length - 1, 0, length - 1)
                dp[residue::w] = new

    print(dp[W])


if __name__ == '__main__':
    solve()

