import sys


def main():
    inp = sys.stdin.buffer
    k = int(inp.readline())
    s = inp.readline().strip()
    t = inp.readline().strip()
    n, m = len(s), len(t)

    if abs(n - m) > k:
        print('No')
        return

    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        print('Yes')
        return

    # For each diagonal i-j, keep the furthest reachable position i.
    prev = {0: x}
    for edits in range(1, k + 1):
        cur = {}
        for d in range(max(-edits, -m), min(edits, n) + 1):
            x = prev.get(d, -1)

            # Replace a character.
            a = prev.get(d, -1)
            if a >= 0 and a < n and a - d < m:
                x = a + 1

            # Delete a character of s.
            a = prev.get(d - 1, -1)
            if a >= 0 and a < n:
                x = max(x, a + 1)

            # Insert a character from t.
            a = prev.get(d + 1, -1)
            if a >= 0 and a - (d + 1) < m:
                x = max(x, a)

            if x < 0:
                continue
            y = x - d
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1

            if x == n and y == m:
                print('Yes')
                return
            cur[d] = x
        prev = cur

    print('No')


if __name__ == '__main__':
    main()

