from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        reachable = [1] * len(nums)
        targets = [1 << value for value in nums]
        masks = [(bit << 1) - 1 for bit in targets]
        done = [value == 0 for value in nums]
        remaining = sum(not x for x in done)
        if remaining == 0:
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if done[i]:
                    continue
                reachable[i] = (reachable[i] | (reachable[i] << value)) & masks[i]
                if reachable[i] & targets[i]:
                    done[i] = True
                    remaining -= 1
            if remaining == 0:
                return k
        return -1

