import heapq
from math import isqrt

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        upper = 10 ** len(str(n))
        lower = upper // 10
        prime = bytearray(b'\x01') * upper
        prime[0] = prime[1] = 0
        for p in range(2, isqrt(upper - 1) + 1):
            if prime[p]:
                start = p * p
                prime[start:upper:p] = b'\x00' * ((upper - 1 - start) // p + 1)
        if prime[n] or prime[m]:
            return -1
        dist = [float('inf')] * upper
        dist[n] = n
        heap = [(n, n)]
        places = []
        p = 1
        while p < upper:
            places.append(p)
            p *= 10
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for p in places:
                digit = x // p % 10
                if digit < 9:
                    y = x + p
                    new_cost = cost + y
                    if not prime[y] and new_cost < dist[y]:
                        dist[y] = new_cost
                        heapq.heappush(heap, (new_cost, y))
                if digit > 0:
                    y = x - p
                    if y >= lower and not prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))
        return -1

