from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        positions = [[] for _ in range(26)]
        for j in range(m, 0, -1):
            positions[ord(pattern[j - 1]) - 97].append(j)

        targeted = set(targetIndices)
        # dp[j]: minimum targeted characters used to match pattern[:j].
        dp = [m + 1] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            cost = int(i in targeted)
            # Descending updates prevent using this source character twice.
            for j in positions[ord(ch) - 97]:
                candidate = dp[j - 1] + cost
                if candidate < dp[j]:
                    dp[j] = candidate

        return len(targetIndices) - dp[m]

