class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        transitions = []
        for a, b in pairs:
            transitions.append([k for k, (x, y) in enumerate(pairs) if x != a and y != b])
        dp = [cost[0][a] + cost[n - 1][b] for a, b in pairs]
        for i in range(1, n // 2):
            left, right = cost[i], cost[n - 1 - i]
            nxt = []
            for (a, b), (p, q, r) in zip(pairs, transitions):
                nxt.append(left[a] + right[b] + min(dp[p], dp[q], dp[r]))
            dp = nxt
        return min(dp)

